import json, sys

def trunc(s, n=350):
    if isinstance(s, str):
        return s[:n] + (f"...[{len(s)} chars]" if len(s) > n else "")
    return s

def summarize_content(content):
    if isinstance(content, str):
        return trunc(content)
    if isinstance(content, list):
        out = []
        for item in content:
            if isinstance(item, dict):
                t = item.get("type")
                if t == "text":
                    out.append({"type":"text","text":trunc(item.get("text",""))})
                elif t == "tool_use":
                    out.append({"type":"tool_use","name":item.get("name"),"input":trunc(json.dumps(item.get("input",{})),300)})
                elif t == "tool_result":
                    c = item.get("content")
                    if isinstance(c, list):
                        c = " ".join(trunc(x.get("text",""),300) if isinstance(x,dict) else str(x) for x in c)
                    out.append({"type":"tool_result","content":trunc(str(c),300)})
                else:
                    out.append({"type":t, "raw":trunc(json.dumps(item),200)})
            else:
                out.append(trunc(str(item),200))
        return out
    return trunc(str(content))

fn = sys.argv[1]
with open(fn) as f:
    for i, line in enumerate(f, 1):
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except Exception as e:
            print(f"LINE {i}: PARSE ERROR {e}")
            continue
        typ = obj.get("type")
        ts = obj.get("timestamp")
        role = None
        msg = obj.get("message")
        summary = None
        if msg and isinstance(msg, dict):
            role = msg.get("role")
            summary = summarize_content(msg.get("content"))
        else:
            summary = trunc(json.dumps({k:v for k,v in obj.items() if k not in ("timestamp","type")}), 300)
        print(f"L{i} | {ts} | {typ} | {role} | {json.dumps(summary, default=str)[:600]}")
PYEOF
echo done

