import { sep } from 'node:path';
import { fileURLToPath } from 'node:url';
import { realpathSync } from 'node:fs';
import { finding } from '../../../engine/checks/helpers/findings.mjs';
import { runRule } from '../../../engine/checks/helpers/work.mjs';
import { buildContext } from '../../../engine/checks/helpers/repo-context.mjs';
import { LOCAL_PACKS_SUBDIR } from '../../../engine/pack_loader/pack-registry.mjs';

// The write-surface gate for this pack's own runs — extract, dedup, and the two
// sweeps. Every one of them works the repo's own local packs and nothing else,
// and extract's PR auto-merges with no human review, so the boundary needs a
// machine guarantee, not a prose request: when a branch carries one of those
// runs' pinned commit subjects, every path it touches — added, modified, or
// deleted — must sit under .claudinite/local/packs/.
//
// The trigger is the run's whole pinned title, NOT the bare "Claudinite growth:"
// prefix the whole lifecycle shares, because a sibling run under that prefix has a
// wider write surface by design, and keying on the prefix would red it. A run whose
// title this list doesn't carry is simply not this rule's business — the canon-side
// twins of the two sweeps title themselves "Claudinite canon: …" and are bounded by
// their own tasks' policies over the packs/ shelf.
//
// A growth run marks ITSELF via that title, so this rule self-gates and runs
// everywhere the pack is active: at the session Stop hook (work scope), and as
// a CLI on every PR in the canon repo's CI.
//
// git emits '/'-separated paths, so the platform-joined constant is normalized.
const LOCAL_ROOT = `${LOCAL_PACKS_SUBDIR.split(sep).join('/')}/`;

// This pack's runs, by the exact titles their task docs pin. `conversation
// extract` is the pre-merge title of extract's conversation half, still in use
// wherever a consumer mounts a canon older than the one-task merge.
const GROWTH_RUN = /^Claudinite growth: (?:extract lessons|conversation extract|dedup\b|prose to checks|rule revalidation)/;

const inSurface = (p) => p.startsWith(LOCAL_ROOT);

const rule = {
  id: 'growth-write-scope',
  on_fail: 'block',
  scope: 'work',
  doc: 'packs/claudinite-growth/README.md',
  description: 'A growth run (extract, dedup, either sweep) writes only the repo\'s own local packs',
  why: 'extract auto-merges its PR with no human review and the rest run unattended; every one of them improves the repo\'s own packs, so a write outside .claudinite/local/packs/ — the canon it reads against, or the project\'s own code — escapes the review-by-blast-radius boundary the growth lifecycle is built on',

  run(work) {
    if (work.onDefaultBranch()) return [];
    if (!work.commits.some((m) => GROWTH_RUN.test(m))) return [];
    const touched = [...new Set([...work.changedFiles, ...work.deleted])];
    return touched
      .filter((p) => !inSurface(p))
      .sort()
      .map((p) => finding(rule, {
        file: p,
        what: `a growth run touched ${p}, outside ${LOCAL_ROOT}`,
        fix: 'a growth run improves the repo\'s own packs, never the canon or the project\'s code — keep the whole write surface inside the local packs; a site-tied lesson lands as the owning pack\'s entry naming the site, and the same action over a canon\'s packs/ shelf is a claudinite-canon-curation task\'s',
      }));
  },
};

export default rule;

// CLI body — a CI gate runs this on every PR (self-gating, ~nothing on a branch
// that is not a growth run):
// `node .claudinite/shared/packs/claudinite-growth/workRules/growth-write-scope.mjs [root]`.
//   exit 0 — not a growth run, or every touched path is under the local packs
//   exit 1 — a growth run touched a path outside the local packs
export function runCli(root = process.cwd()) {
  const ctx = buildContext({ root, mode: 'changed' });
  if (!ctx.mergeBase) {
    // Without a merge-base there is no diff — and no branch commits — to read,
    // so there is nothing to self-gate on. This step runs on EVERY PR, so
    // refusing here would fail every history-less checkout on an ordinary one;
    // the Stop-hook run still covers the session side.
    console.log('growth-write-scope: no merge-base with the base branch — nothing to scope.');
    return;
  }
  const findings = runRule(rule, ctx);
  if (findings.length) {
    console.error(`growth-write-scope: FAIL — a growth run may write only under ${LOCAL_ROOT}, but this branch also touches ${findings.length} path(s):`);
    for (const f of findings) console.error(`  - ${f.file}`);
    console.error('\nA growth run improves the repo\'s own packs, never the canon or the project\'s code — keep the whole write surface inside the local packs.');
    process.exitCode = 1;
    return;
  }
  console.log('growth-write-scope: OK — not a growth run, or every touched path is under the local packs.');
}

if (process.argv[1] && realpathSync(process.argv[1]) === fileURLToPath(import.meta.url)) {
  runCli(process.argv[2] || process.cwd());
}

