86	          : head.length > base.length ? `from ${base.length} to ${head.length} characters`
87	            : null;
88	        if (grew) {
89	          findings.push(finding(rule, {
90	            file,
91	            what: `a dedup run grew ${file} ${grew} — a prune/strip removes duplicated text, it never grows the pack`,
92	            fix: 'strip each covered item down to its project residue (a deletion that shrinks the entry); if you are keeping an item, leave it unchanged rather than rewording it',
93	          }));
94	        }
95	      }
96	    }
97	
98	    return findings;
99	  },
100	};
101	
102	export default rule;
